submissions.repair-original-fabric-repeat-cuts:
def solve(data):
    cuts = []
    for line in data['lines']:
        if line['state'] != 'approved':
            continue
        repeat = line['repeat_cm']
        remaining = (line['need_cm'] + repeat - 1) // repeat
        capacity = data['limit_cm'] // repeat
        while remaining:
            count = min(remaining, capacity)
            cuts.append({'fabric': line['fabric'], 'cut_cm': count * repeat})
            remaining -= count
    return cuts

submissions.repair-original-gate-dispatch-sequence-r:
def solve(data):
    last = data['last']
    issued = []
    for event in data['events']:
        if event == 'issue':
            last += 1
            issued.append(last)
        elif event == 'rollover' and last > data['threshold']:
            last = 0
    return {'issued': issued, 'last': last}

